/usr/bin/zsh -lc "cat > candidate.sv <<'SV'
module TopModule (
    input logic [15:0] a, b, c, d, e, f, g, h, i,
    input logic [3:0] sel,
    output logic [15:0] out
);
    always_comb begin
        case (sel)
            4'd0: out = a;
            4'd1: out = b;
            4'd2: out = c;
            4'd3: out = d;
            4'd4: out = e;
            4'd5: out = f;
            4'd6: out = g;
            4'd7: out = h;
            4'd8: out = i;
            default: out = 16'hffff;
        endcase
    end
endmodule
SV
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'SV'
"'`timescale 1ns/1ps
module dev_tb;
    logic [15:0] data [0:8];
    logic [3:0] sel;
    wire [15:0] out;
    logic [15:0] expected;
    logic [31:0] rng = 32'"'hcafe1234;
    integer checks = 0;
    integer n, s, bit_idx, p;
    TopModule dut (.a(data[0]), .b(data[1]), .c(data[2]),
        .d(data[3]), .e(data[4]), .f(data[5]), .g(data[6]),
        .h(data[7]), .i(data[8]), .sel(sel), .out(out));
    task automatic check;
        begin
            #1;
            expected = (sel < 9) ? data[sel] : 16'hffff;
            if (out "'!== expected)
                $fatal(1, "FAIL sel=%0d expected=%h actual=%h", sel, expected, out);
            checks = checks + 1;
        end
    endtask
    initial begin
        for (p=0; p<9; p=p+1) data[p] = 16'"'h1234 "'^ (p * 16'"'h1111);
        for (s=0; s<16; s=s+1) begin sel=s; check(); end
        for (n=0; n<2; n=n+1) begin
            for (p=0; p<9; p=p+1) data[p] = n ? 16'hffff : 16'h0000;
            for (s=0; s<16; s=s+1) begin sel=s; check(); end
        end
        for (s=0; s<9; s=s+1) begin
            sel=s;
            for (bit_idx=0; bit_idx<16; bit_idx=bit_idx+1) begin
                for (p=0; p<9; p=p+1) data[p]=16'h0000;
                data[s]=16'h0001 << bit_idx;
                check();
                for (p=0; p<9; p=p+1) data[p]=16'hffff;
                data[s]=~(16'h0001 << bit_idx);
                check();
            end
        end
        for (s=0; s<16; s=s+1) begin
            sel=s;
            for (n=0; n<128; n=n+1) begin
                for (p=0; p<9; p=p+1) begin
                    rng=rng "'^ (rng << 13);
                    rng=rng ''^ (rng >> 17);
                    rng=rng ''^ (rng << 5);
                    data[p]=rng[15:0];
                end
                check();
            end
        end
        $display("PASS: %0d comparisons", checks);
        $finish;
    end
    initial begin
        #10000;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
SV
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
cat compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
    cat simulation.log
else
    simulation_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > development_status.log'

